import{_ as e,o as a,c as o,a5 as d}from"./chunks/framework.B-qY3dMa.js";const p=JSON.parse('{"title":"为什么报 context_length_exceeded？","description":"","frontmatter":{"title":"为什么报 context_length_exceeded？","date":"2026-05-18T00:00:00.000Z","category":"常见问题","tags":["报错","上下文","Token超限"]},"headers":[],"relativePath":"faq/context-length-exceeded.md","filePath":"faq/context-length-exceeded.md","lastUpdated":1779089963000}'),r={name:"faq/context-length-exceeded.md"};function n(l,t,s,i,c,h){return a(),o("div",null,[...t[0]||(t[0]=[d('<h2 id="错误原因" tabindex="-1">错误原因 <a class="header-anchor" href="#错误原因" aria-label="Permalink to &quot;错误原因&quot;">​</a></h2><p>模型每次处理的文本有上限（上下文窗口），当你的请求超出这个上限就会报错。</p><p>实际消耗 = 系统 Prompt + <strong>全部历史消息</strong> + 本次输入 + 预留输出空间</p><p>很多用户不知道，客户端默认会把所有历史对话都带上，聊几十轮后 Token 会悄悄积累到超限。</p><h2 id="不同模型上下文上限" tabindex="-1">不同模型上下文上限 <a class="header-anchor" href="#不同模型上下文上限" aria-label="Permalink to &quot;不同模型上下文上限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>上下文窗口</th></tr></thead><tbody><tr><td>Claude 3.5/3.7 系列</td><td>200k tokens</td></tr><tr><td>GPT-4o</td><td>128k tokens</td></tr><tr><td>DeepSeek V3</td><td>64k tokens</td></tr><tr><td>Gemini 1.5 Pro</td><td>1M tokens</td></tr></tbody></table><h2 id="解决方法" tabindex="-1">解决方法 <a class="header-anchor" href="#解决方法" aria-label="Permalink to &quot;解决方法&quot;">​</a></h2><ul><li><strong>清空历史对话</strong>：在客户端开启新对话，不要在一个超长对话里继续</li><li><strong>缩短系统 Prompt</strong>：检查是否有不必要的长系统提示词</li><li><strong>换更大窗口的模型</strong>：任务需要长上下文时，选 Claude 或 Gemini</li><li><strong>代码层面</strong>：实现历史消息裁剪，只保留最近 N 轮</li></ul>',8)])])}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
